54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
115	        owner.setTelephone(normalizedTelephone);
116	        owner.setEmail(normalizeEmail(owner.getEmail()));
117	        owner.setAddress(normalizeAddress(owner.getAddress()));
118	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
119	        if (effectiveRegistrationDate == null) {
120	            effectiveRegistrationDate = LocalDate.now();
121	        }
122	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
123	        owner.setRegistrationDate(effectiveRegistrationDate);
124	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
125	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
126	                "the maximum number of owners that may be created today has been reached");
127	        }
128	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
129	        if (sharesHousehold) {
130	            this.clinicService.assignHousehold(owner);
131	        }
132	        if (isIdentityKeyInUse(identityKeyFor(owner), null)) {
133	            throw new ResponseStatusException(HttpStatus.CONFLICT,
134	                "an owner with the same identity already exists");
135	        }
136	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
137	            throw new ResponseStatusException(HttpStatus.CONFLICT,
138	                "city has reached its maximum number of owners");
139	        }
140	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
141	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
142	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
143	        owner.setBulkSignupWarning(
144	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
145	        this.clinicService.saveOwner(owner);
146	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
147	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
148	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
149	            ownerDto.getMembershipLevel());
150	        headers.setLocation(UriComponentsBuilder.newInstance()
151	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
152	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
158	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
159	        if (currentOwner == null) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        currentOwner.setAddress(ownerFieldsDto.getAddress());
163	        currentOwner.setCity(ownerFieldsDto.getCity());
164	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
165	        currentOwner.setLastName(ownerFieldsDto.getLastName());
166	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
167	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
168	        this.clinicService.saveOwner(currentOwner);
169	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Transactional
174	    @Override
175	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
176	        Owner owner = this.clinicService.findOwnerById(ownerId);
177	        if (owner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        this.clinicService.deleteOwner(owner);
181	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
187	        Owner owner = this.clinicService.findOwnerById(ownerId);
188	        if (owner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        HttpHeaders headers = new HttpHeaders();
192	        Pet pet = petMapper.toPet(petFieldsDto);
193	        owner.setId(ownerId);
194	        pet.setOwner(owner);
195	        pet.getType().setName(null);
196	        this.clinicService.savePet(pet);
197	        PetDto petDto = petMapper.toPetDto(pet);
198	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
199	            .buildAndExpand(pet.getId()).toUri());
200	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
206	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
207	        if (currentOwner != null) {
208	            Pet currentPet = this.clinicService.findPetById(petId);
209	            if (currentPet != null) {
210	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
211	                currentPet.setName(petFieldsDto.getName());
212	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
213	                this.clinicService.savePet(currentPet);
214	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
215	            }
216	        }
217	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
223	        HttpHeaders headers = new HttpHeaders();
224	        Visit visit = visitMapper.toVisit(visitFieldsDto);
225	        Pet pet = new Pet();
226	        pet.setId(petId);
227	        visit.setPet(pet);
228	        this.clinicService.saveVisit(visit);
229	        VisitDto visitDto = visitMapper.toVisitDto(visit);
230	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
231	            .buildAndExpand(visit.getId()).toUri());
232	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
233	    }
234	
235	
236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
239	        Owner owner = this.clinicService.findOwnerById(ownerId);
240	        if (owner != null) {
241	            Pet pet = owner.getPet(petId);
242	            if (pet != null) {
243	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
244	            }
245	        }
246	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	    }
248	
249	    /**
250	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is
251	     * the upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
252	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
253	     * owners that already live in that city (e.g. {@code 'LON-SMI-0007'}).
254	     *
255	     * @param city     the owner's city
256	     * @param lastName the owner's last name
257	     * @return the assigned customer code
258	     */
259	    private String nextCustomerCode(String city, String lastName) {
260	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
261	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
262	        int sequence = countOwnersInCity(city) + 1;
263	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
264	    }
265	
266	    /**
267	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
268	     * owner's city already contains this many owners.
269	     */
270	    private static final int CITY_CAPACITY = 50;
271	
272	    /**
273	     * The maximum number of owners that may be created on a single day. A create is rejected with
274	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
275	     * {@code registrationDate}.
276	     */
277	    private static final int DAILY_CREATE_LIMIT = 100;
278	
279	    /**
280	     * The number of owners that must already have been created for the current day before a new
281	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
282	     * owners already carry today's {@code registrationDate}.
283	     */
284	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
285	
286	    /**
287	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
288	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
289	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
290	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
291	     * falls on a business day.
292	     *
293	     * @param date the effective registration date
294	     * @return the same date when it is a weekday, otherwise the following Monday
295	     */
296	    private static LocalDate rollToBusinessDay(LocalDate date) {
297	        return switch (date.getDayOfWeek()) {
298	            case SATURDAY -> date.plusDays(2);
299	            case SUNDAY -> date.plusDays(1);
300	            default -> date;
301	        };
302	    }
303	
304	    /**
305	     * Counts the existing owners whose {@code registrationDate} equals the given (already
306	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
307	     * business day. Called before a new owner is saved, so the returned value reflects the number of
308	     * owners created for that day prior to this create.
309	     *
310	     * @param date the adjusted business-day registration date to count against
311	     * @return the number of existing owners registered on that date
312	     */
313	    private int countOwnersRegisteredOn(LocalDate date) {
314	        return (int) this.clinicService.findAllOwners().stream()
315	            .filter(existing -> date.equals(existing.getRegistrationDate()))
316	            .count();
317	    }
318	
319	    /**
320	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
321	     *
322	     * @param city the city to count owners for
323	     * @return the number of existing owners in that city
324	     */
325	    private int countOwnersInCity(String city) {
326	        return (int) this.clinicService.findAllOwners().stream()
327	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
328	            .count();
329	    }
330	
331	    /**
332	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
333	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}).
334	     *
335	     * @param customerCode     the owner's assigned customer code
336	     * @param registrationDate the owner's registration date
337	     * @return the assigned membership number
338	     */
339	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
340	        String yy = String.format("%02d", registrationDate.getYear() % 100);
341	        return String.format("%s-M%s", customerCode, yy);
342	    }
343	
344	    /**
345	     * Counts the existing owners that already share the given first name and last name, comparing
346	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
347	     * the number of namesakes that existed prior to this create.
348	     *
349	     * @param firstName the new owner's first name
350	     * @param lastName  the new owner's last name
351	     * @return the number of existing owners with the same first and last name
352	     */
353	    private int countNamesakes(String firstName, String lastName) {
354	        int count = 0;
355	        for (Owner existing : this.clinicService.findAllOwners()) {
356	            if (firstName.equalsIgnoreCase(existing.getFirstName())
357	                && lastName.equalsIgnoreCase(existing.getLastName())) {
358	                count++;
359	            }
360	        }
361	        return count;
362	    }
363	
364	    /**
365	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
366	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
367	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
368	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
369	     * string is what gets stored and returned.
370	     *
371	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
372	     *
373	     * <p>Once in E.164 form the national-number length is validated against the country code: a
374	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
375	     * number exactly 10 (see {@link #COUNTRY_NATIONAL_LENGTHS}). Country codes without a configured
376	     * rule are accepted on the general 8-to-15 digit length alone.
377	     *
378	     * @param telephone the raw telephone value supplied by the client
379	     * @return the normalized E.164 telephone number
380	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
381	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
382	     *                                 after the {@code '+'}, or the wrong national-number length for
383	     *                                 its country code)
384	     */
385	    private static String normalizeTelephone(String telephone) {
386	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
387	        String digits;
388	        if (cleaned.startsWith("+")) {
389	            digits = cleaned.substring(1);
390	        } else {
391	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
392	            digits = "61" + national;
393	        }
394	        if (!digits.matches("[0-9]{8,15}")) {
395	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
396	                "telephone could not be normalized to a valid E.164 number");
397	        }
398	        validateNationalNumberLength(digits);
399	        return "+" + digits;
400	    }
401	
402	    /**
403	     * International dialling codes mapped to the exact number of national (subscriber) digits an
404	     * E.164 number for that country must carry: {@code +61} (Australia) requires 9 national digits
405	     * and {@code +1} (NANP) requires 10. Country codes absent from this map have no length rule.
406	     */
407	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
408	
409	    /**
410	     * Validates the national-number length of an E.164 number (its digits, without the leading
411	     * {@code '+'}) against its country code. The longest configured dialling code that prefixes the
412	     * number selects the rule; if none is configured the number passes (only the general 8-to-15
413	     * digit rule applies).
414	     *
415	     * @param digits the E.164 digits without the leading {@code '+'}
416	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
417	     *                                 digits does not match the country code's required length
418	     */
419	    private static void validateNationalNumberLength(String digits) {
420	        COUNTRY_NATIONAL_LENGTHS.keySet().stream()
421	            .filter(digits::startsWith)
422	            .max(Comparator.comparingInt(String::length))
423	            .ifPresent(code -> {
424	                int nationalLength = digits.length() - code.length();
425	                if (nationalLength != COUNTRY_NATIONAL_LENGTHS.get(code)) {
426	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
427	                        "telephone must have " + COUNTRY_NATIONAL_LENGTHS.get(code)
428	                            + " national digits for country code +" + code);
429	                }
430	            });
431	    }
432	
433	    /**
434	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
435	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
436	     *
437	     * @param telephone the stored telephone value, possibly {@code null}
438	     * @return the E.164 form, or the raw value when it cannot be normalized
439	     */
440	    private static String toComparableTelephone(String telephone) {
441	        try {
442	            return normalizeTelephone(telephone);
443	        } catch (ResponseStatusException ex) {
444	            return telephone;
445	        }
446	    }
447	
448	    /**
449	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
450	     * containing at least one dot, none of the three sections containing whitespace or an
451	     * additional {@code @}.
452	     */
453	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
454	
455	    /**
456	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
457	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
458	     * value is then stored and returned lower-cased.
459	     *
460	     * @param email the raw email value supplied by the client, possibly {@code null}
461	     * @return the lower-cased email, or {@code null} when none was supplied
462	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
463	     *                                 is not a syntactically valid address
464	     */
465	    private static String normalizeEmail(String email) {
466	        if (email == null) {
467	            return null;
468	        }
469	        if (!EMAIL_PATTERN.matcher(email).matches()) {
470	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
471	                "email must be a syntactically valid address");
472	        }
473	        return email.toLowerCase(Locale.ROOT);
474	    }
475	
476	    /**
477	     * Common street-type abbreviations expanded to their full word during address normalization.
478	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
479	     */
480	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
481	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
482	
483	    /**
484	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
485	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
486	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
487	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
488	     * address comparison (household duplicate detection and the shared household id).
489	     *
490	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
491	     *
492	     * @param address the raw address supplied by the client, possibly {@code null}
493	     * @return the normalized address
494	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
495	     *                                 after normalization (required field)
496	     */
497	    private static String normalizeAddress(String address) {
498	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
499	        if (collapsed.isEmpty()) {
500	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
501	                "address must not be blank");
502	        }
503	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
504	        StringBuilder normalized = new StringBuilder();
505	        for (int i = 0; i < tokens.length; i++) {
506	            if (i > 0) {
507	                normalized.append(' ');
508	            }
509	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
510	        }
511	        return normalized.toString();
512	    }
513	
514	    /**
515	     * Builds an owner's duplicate-detection identity key: the normalized E.164 telephone, the
516	     * lower-cased email (empty when none) and the household id (empty when none), joined with
517	     * {@code '|'}. This single derived key subsumes what used to be separate telephone, email and
518	     * household duplicate checks: two owners are duplicates only when their whole identity keys are
519	     * equal. Because the telephone is part of the key, two members of the same household (same
520	     * {@code householdId}) with different telephones have different keys and are both allowed.
521	     *
522	     * @param owner the owner whose (already normalized) fields form the key
523	     * @return the identity key
524	     */
525	    private String identityKeyFor(Owner owner) {
526	        return identityKey(toComparableTelephone(owner.getTelephone()),
527	            owner.getEmail(), owner.getHouseholdId());
528	    }
529	
530	    /**
531	     * Assembles an identity key from its three normalized parts, treating a {@code null} email or
532	     * household id as empty so the key is always three {@code '|'}-joined segments.
533	     */
534	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
535	        return normalizedTelephone + "|"
536	            + (email == null ? "" : email) + "|"
537	            + (householdId == null ? "" : householdId);
538	    }
539	
540	    /**
541	     * Determines whether the given whole identity key already belongs to any owner other than the
542	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
543	     * create). Only an exact full-key match counts as a duplicate.
544	     *
545	     * @param identityKey the identity key to look for
546	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
547	     * @return {@code true} if another owner already has the same identity key
548	     */
549	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
550	        for (Owner existing : this.clinicService.findAllOwners()) {
551	            if (excludeId != null && excludeId.equals(existing.getId())) {
552	                continue;
553	            }
554	            if (identityKey.equals(identityKeyFor(existing))) {
555	                return true;
556	            }
557	        }
558	        return false;
559	    }
560	
561	}
